#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int a, b;
    std::cin >> a >> b;
    int x = std::min(a, b);
    int y = std::max(a, b);
    std::map<int, int> m = {
        {1, std::min(y % 6, 6 - y % 6)},
        {2, 2 * (y == 3 || y == 7) + 4 * (y == 2)}
    };
    int value;
    if (m.count(x)) {
        value = x * y - m[x];
    } else {
        value = x * y - ((x & 1) * (y & 1));
    }
    std::cout << value << std::endl;
    return 0;
}
